import { BookedTickets, Seat } from "@/icons";
import { use, useEffect, useRef, useState } from "react";
import Input from "../form/input/InputField";
import Label from "../form/Label";
import { handle } from "@/consonants";
import Select from "../form/Select";
import { useTranslations } from "next-intl";

export default function SeatSelection({
  seats,
  setSeats,
  dublicateSeat,
  setdublicateSeat,
  disabled,
  vehicleType = "bus",
  edit,
  setBookedSeats,
  bookedSeats,
}) {
  const addTransportationTrans = useTranslations("addTransportationsPage");
  const [rows, setRows] = useState(vehicleType === "car" ? 1 : 5);
  const [seatsPerRow, setSeatsPerRow] = useState(vehicleType === "car" ? 3 : 4);

  const generateSeats = () => {
    const layout = [];
    let seatName = vehicleType === "car" ? 1 : 0;
    for (let i = 0; i < rows; i++) {
      const row = [];
      for (let j = 0; j < seatsPerRow; j++) {
        const id = `${++seatName}`;
        row.push({ id, state: "Empty" });
      }
      layout.push(row);
    }
    return layout;
  };

  const [seatSelectionState, setSeatSelectionState] = useState("Empty");

  useEffect(() => {
    !disabled && !edit && setSeats(generateSeats());
  }, [rows, seatsPerRow]);

  const MaleSvg = () => {
    return (
      <svg
        width="22"
        height="23"
        viewBox="0 0 27 28"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        xmlnsXlink="http://www.w3.org/1999/xlink"
      >
        <rect
          width="26"
          height="30"
          transform="matrix(-1 0 0 1 26.7229 0.651367)"
          fill="url(#pattern0_72_1087)"
        />
        <defs>
          <pattern
            id="pattern0_72_1087"
            patternContentUnits="objectBoundingBox"
            width="1"
            height="1"
          >
            <use
              xlinkHref="#image0_72_1087"
              transform="matrix(0.00225361 0 0 0.00195312 -0.0769231 0)"
            />
          </pattern>
          <image
            id="image0_72_1087"
            width="512"
            height="512"
            preserveAspectRatio="none"
            xlinkHref="data:image/png;base64,"
          />
        </defs>
      </svg>
    );
  };

  const FemaleSvg = () => (
    <svg
      width="22"
      height="23"
      viewBox="0 0 24 26"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
    >
      <rect width="24" height="26" fill="url(#pattern0_201_1677)" />
      <defs>
        <pattern
          id="pattern0_201_1677"
          patternContentUnits="objectBoundingBox"
          width="1"
          height="1"
        >
          <use
            xlinkHref="#image0_201_1677"
            transform="matrix(0.00211589 0 0 0.00195312 -0.0416667 0)"
          />
        </pattern>
        <image
          id="image0_201_1677"
          width="512"
          height="512"
          preserveAspectRatio="none"
          xlinkHref="data:image/png;base64,"
        />
      </defs>
    </svg>
  );

  const states = {
    Unavailable: "#B1B1B16E",
    Empty: "#E9F3FE",
    Reserved: "#4895EF",
    "Male Reserved": "#8F87F1",
    "Female Reserved": "#FFB8E0",
  };

  const Tyre = ({ left }) => {
    return (
      <div
        className={`w-[15px] h-full bg-black tyre rounded-[3px] ${
          rows < 4 ? "!h-[80%]" : ""
        } ${left ? "translate-x-[-15px]" : "translate-x-[15px]"}`}
      ></div>
    );
  };

  useEffect(() => {
    if (!edit) {
      if (vehicleType === "car") {
        setRows(1);
        setSeatsPerRow(3);
        !disabled &&
          setTimeout(() => {
            setSeats((e) => {
              const temp = [...e];
              temp.unshift([{ id: 1, state: "Empty" }]);
              return temp;
            });
          }, 200);
      } else {
        setRows(5);
        setSeatsPerRow(4);
      }
    }
  }, [vehicleType]);

  const SeatMap = {
    Reserved: "unknown",
    "Male Reserved": "male",
    "Female Reserved": "female",
  };

  const CheckSeatExsists = (id) => {
    if (!bookedSeats) return false;
    for (const [gender, seatArr] of Object.entries(bookedSeats)) {
      if (seatArr.includes(id)) {
        return Object.entries(SeatMap).find(
          ([key, value]) => value === gender
        )?.[0];
      }
    }
    return false;
  };

  return (
    <div id="seatSelection" dir="ltr">
      <div className="w-full mx-auto">
        {!disabled && vehicleType === "bus" && (
          <div className="mb-8">
            <div className="flex flex-wrap gap-6 mb-6">
              <div className="flex-1">
                <Label>{addTransportationTrans("NumberOfRows")}</Label>
                <Input
                  type="number"
                  required={true}
                  name={"rows"}
                  id={"rows"}
                  defaultValue={rows}
                  value={rows}
                  onChange={(e) =>
                    e.target.value < 50 &&
                    e.target.value >= 2 &&
                    setRows(+e.target.value)
                  }
                  min={2}
                  max={50}
                />
              </div>

              <div className="flex-1">
                <Label>{addTransportationTrans("BusType")}</Label>
                <Select
                  defaultValue={"2x2"}
                  name="busType"
                  id="busType"
                  options={[
                    {
                      label: addTransportationTrans("VipBus"),
                      value: "2x1",
                    },
                    {
                      label: addTransportationTrans("Bus580"),
                      value: "2x2",
                    },
                  ]}
                  onChange={(e) => {
                    if (e === "2x2") {
                      setSeatsPerRow(4);
                    } else {
                      setSeatsPerRow(3);
                    }
                  }}
                  className=""
                />
              </div>
            </div>
          </div>
        )}

        <div className="relative flex md:flex-row flex-col w-full md:gap-[100px]">
          <div className="sticky top-[90px] bg-white dark:bg-[#171f2f] flex flex-wrap z-[30]  py-[10px] flex-row md:flex-col items-start gap-4 mb-2">
            {Object.keys(states).map((it, ind) => (
              <div
                key={ind}
                onClick={() =>
                  (!disabled || (setBookedSeats && it !== "Unavailable")) &&
                  setSeatSelectionState(it)
                }
                className="flex items-center cursor-pointer"
              >
                <span
                  style={{ background: states[it] }}
                  type="button"
                  className={`w-6 h-8 md:w-8 mr-2 bg-blue-500 rounded flex-center ${
                    it === seatSelectionState
                      ? "border-[2px] border-primary-black"
                      : ""
                  }`}
                >
                  {it.includes("Male") ? (
                    <MaleSvg />
                  ) : (
                    it.includes("Female") && <FemaleSvg />
                  )}
                </span>

                <span className="text-[12px] md:text-[14px] dark:text-gray-300">
                  {addTransportationTrans(it.replace(/\s/g, ""))}
                </span>
              </div>
            ))}
          </div>

          <div
            className={`relative flex flex-col w-max border border-[#B5BBC1] ${
              vehicleType === "car" ? "rounded-[25px]" : "rounded-t-[25px]"
            }`}
          >
            <div
              className={`bg-[#D9D9D9] w-full rounded-t-[25px] mb-[15px] ${
                vehicleType === "car" ? "h-[76px]" : "h-[35px] "
              }`}
            >
              <span
                className={`[&_svg]:w-[30px] [&_svg]:h-[30px] inline-block translate-x-[15px] translate-y-[15px] ${
                  vehicleType === "car" ? "translate-y-[55px]" : ""
                }`}
              >
                {handle}
              </span>
            </div>
            <div className="flex flex-row justify-between mb-[10px] px-[5px]">
              <div
                className={`flex flex-row justify-between gap-[5px] ${
                  vehicleType === "car" ? "absolute translate-y-[10px]" : ""
                }`}
              >
                <div
                  className={`w-13 h-13 md:h-16 md:w-16 border dark:border-gray-500 relative flex-center flex-col cursor-pointer transition-all bg-[#B1B1B16E]`}
                ></div>
                {seatsPerRow === 4 && setSeats && (
                  <div
                    className={`w-13 h-13 md:h-16 md:w-16 border dark:border-gray-500 relative flex-center flex-col cursor-pointer transition-all bg-[#B1B1B16E]`}
                  ></div>
                )}
              </div>
              <div className="flex flex-row justify-between gap-[5px]">
                {vehicleType !== "car" && (
                  <>
                    <div
                      className={`w-13 h-13 md:h-16 md:w-16 border dark:border-gray-500 relative flex-center flex-col cursor-pointer transition-all bg-[#B1B1B16E]`}
                    ></div>
                    <div
                      className={`w-13 h-13 md:h-16 md:w-16 border dark:border-gray-500 relative flex-center flex-col cursor-pointer transition-all bg-[#B1B1B16E]`}
                    ></div>
                  </>
                )}
              </div>
            </div>
            {/* Front Tyres */}
            <div
              className={`flex flex-row items-center justify-between w-[100%] absolute top-[80px] h-[80px] ${
                vehicleType === "car"
                  ? "translate-y-[-35px]"
                  : rows < 4
                  ? "translate-y-[-20px]"
                  : ""
              }`}
            >
              <Tyre left={true} />
              <Tyre />
            </div>
            {/* Back Tyres */}
            <div
              className={`flex flex-row items-center justify-between w-[100%] absolute bottom-[50px] h-[80px] ${
                vehicleType === "car"
                  ? "translate-y-[35px]"
                  : rows < 4
                  ? "translate-y-[20px]"
                  : ""
              }`}
            >
              <Tyre left={true} />
              <Tyre />
            </div>
            {seats &&
              seats?.map((row, rowIdx) => (
                <div
                  key={rowIdx}
                  className={`relative flex gap-[5px] mb-[10px] px-[5px] ${
                    vehicleType === "car" ? "justify-end" : ""
                  }`}
                >
                  {row.map((seat, seatIdx) => {
                    const gender = !bookedSeats
                      ? false
                      : CheckSeatExsists(seat.id);
                    return (
                      <div key={seatIdx} className={`flex items-center`}>
                        <div
                          style={{
                            backgroundColor:
                              bookedSeats && gender
                                ? states[gender]
                                : states[seat.state],
                          }}
                          className={`w-13 h-13 md:h-16 md:w-16 border dark:border-gray-500 relative flex-center flex-col cursor-pointer transition-all ${
                            dublicateSeat === seat.id
                              ? "border border-red-600"
                              : ""
                          } ${
                            bookedSeats && seat.state !== "Empty"
                              ? "opacity-50"
                              : ""
                          }`}
                          onClick={() => {
                            bookedSeats &&
                              seat.state === "Empty" &&
                              setBookedSeats((prev) => {
                                const temp = { ...prev };
                                Object.keys(temp).forEach((gender) => {
                                  temp[gender] = temp[gender].filter(
                                    (seatId) => seatId !== seat.id
                                  );
                                });

                                if (seatSelectionState !== "Empty") {
                                  temp[SeatMap[seatSelectionState]] = [
                                    ...(temp[SeatMap[seatSelectionState]] ||
                                      []),
                                    seat.id,
                                  ];
                                }

                                return { ...temp };
                              });

                            !disabled &&
                              setSeats((prev) => {
                                const temp = [...prev];
                                temp[rowIdx][seatIdx].state =
                                  seatSelectionState;
                                return [...temp];
                              });
                          }}
                        >
                          {/* <Seat /> */}
                          <input
                            disabled={disabled}
                            onClick={(e) => e.stopPropagation()}
                            className={`z-10 w-10 text-center med-14 dark:!text-black ${
                              bookedSeats ? "pointer-events-none" : ""
                            }`}
                            spellCheck={false}
                            value={seat.id}
                            onChange={(e) => {
                              if (bookedSeats) return false;

                              setdublicateSeat(false);
                              setSeats((prev) => {
                                const temp = [...prev];
                                temp[rowIdx][seatIdx].id =
                                  e.target.value.toUpperCase();
                                return [...temp];
                              });
                            }}
                          />
                        </div>
                        {seatIdx ===
                          Math.floor(seatsPerRow / 2) - (setSeats ? 1 : 2) &&
                          vehicleType !== "car" && (
                            <div
                              key={`aisle-${seatIdx}`}
                              className="w-1 mx-1 bg-gray-200 md:w-12"
                            ></div>
                          )}
                      </div>
                    );
                  })}
                </div>
              ))}
            {vehicleType === "car" && (
              <div
                className={`bg-[#D9D9D9] w-full rounded-b-[25px] h-[76px]`}
              ></div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
